import { syntaxTree } from '@codemirror/language';
import type { Diagnostic } from '@codemirror/lint';
import type { RangeSet } from '@codemirror/state';
import { RangeSetBuilder } from '@codemirror/state';
import type { Decoration, EditorView } from '@codemirror/view';
import type { SyntaxNodeRef, Tree } from '@lezer/common';

import { getTextFromRange } from './get-text.js';
import type { FilterFieldNodeRange } from './tree-conversion.js';
import {
  errorMark,
  postSpotErrorMark,
  preSpotErrorMark,
} from '../decorations/decoration-marks.js';

type FilterFieldErrorMessages = {
  emptyGroupError: string;
  incompleteGroupError: string;
  incompleteStatementError: string;
  invalidOperatorError: string;
  missingKeyError: string;
  missingValueError: string;
  missingOperatorError: string;
  invalidValueError: string;
  incompleteRangeError: string;
  incompleteListError: string;
  invalidLogicalOperator: string;
};

function hasClosingBracket(node: SyntaxNodeRef, tree: Tree) {
  const groupCursor = tree.cursorAt(node.to, -1);
  const isOpen =
    groupCursor.node.name !== 'ClosingBracket' ||
    // A group may have nested groups. In this case, the last node can still match
    // a closing bracket, but the parent node may be a nested group.
    (groupCursor.node.name === 'ClosingBracket' &&
      groupCursor.parent() &&
      groupCursor.node.from !== node.from);

  return !isOpen;
}

const getRenderMessage = (message: string) => {
  const messageWrapperElement = document.createElement('div');
  messageWrapperElement.className = 'strato-filterfield-error-wrapper';
  messageWrapperElement.innerHTML = `<div class="strato-filterfield-error-icon-wrapper"><svg focusable="false"
  role="img"
  aria-hidden="true"
  fill="currentColor"
  width="16"
  height="16"
  xmlns="http://www.w3.org/2000/svg"
  viewBox="0 0 20 20"><path d="M9.2799 6.26743H10.7799V10.7674H9.2799V6.26743Z" />
  <path d="M11.0299 12.7674C11.0299 12.2151 10.5822 11.7674 10.0299 11.7674C9.47762 11.7674 9.0299 12.2151 9.0299 12.7674C9.0299 13.3197 9.47762 13.7674 10.0299 13.7674C10.5822 13.7674 11.0299 13.3197 11.0299 12.7674Z" />
  <path d="M10.737 1.54289C10.3465 1.15237 9.71332 1.15237 9.32279 1.54289L1.54289 9.32279C1.15237 9.71332 1.15237 10.3465 1.54289 10.737L9.32279 18.5169C9.71332 18.9074 10.3465 18.9074 10.737 18.5169L18.5169 10.737C18.9074 10.3465 18.9074 9.71332 18.5169 9.32279L10.737 1.54289ZM10.0299 2.95711L17.1027 10.0299L10.0299 17.1027L2.95711 10.0299L10.0299 2.95711Z" /></svg></div><div>${message}</div>`;
  return () => messageWrapperElement;
};

export function generateErrorsOrDiagnostics(
  view: EditorView,
): RangeSet<Decoration>;
export function generateErrorsOrDiagnostics(
  view: EditorView,
  messages?: FilterFieldErrorMessages,
): Diagnostic[];
export function generateErrorsOrDiagnostics(
  view: EditorView,
  messages?: {
    [key: string]: string;
  },
): RangeSet<Decoration> | Diagnostic[] {
  const diagnostics: Diagnostic[] = [];
  const builder = new RangeSetBuilder<Decoration>();

  const {
    emptyGroupError,
    incompleteGroupError,
    incompleteStatementError,
    missingKeyError,
    missingValueError,
    missingOperatorError,
    invalidOperatorError,
    invalidValueError,
    incompleteRangeError,
    incompleteListError,
    invalidLogicalOperator,
  }: Partial<FilterFieldErrorMessages> = messages ?? {};

  const tree = syntaxTree(view.state);
  const treeCursor = tree.cursor();
  let previousNode: SyntaxNodeRef;

  treeCursor.iterate((node) => {
    // Value starting / ending with a logical operator or multiple logical operators after one another should generate an error.
    // The only nodes allowed right before a logical operator are a FilterStatement or a ClosingBracket.
    if (
      node.name === 'LogicalOperator' &&
      ((previousNode.type.name !== 'FilterStatement' &&
        previousNode.type.name !== 'ClosingBracket') ||
        !node.node.cursor().nextSibling())
    ) {
      const { from, to } = node;
      const charAfter = getTextFromRange(node, view.state.doc).slice(-1);
      const isSpace = charAfter === ' ';
      builder.add(from + 1, isSpace ? to - 1 : to, errorMark);
      diagnostics.push({
        from: from + 1,
        to: isSpace ? to - 1 : to,
        severity: 'error',
        message: '',
        renderMessage: getRenderMessage(invalidLogicalOperator),
      });
    }

    // A group ends with a logical operator
    if (
      previousNode?.type.name === 'LogicalOperator' &&
      node.name === 'ClosingBracket'
    ) {
      builder.add(previousNode.from, previousNode.to, errorMark);
      diagnostics.push({
        from: previousNode.from,
        to: previousNode.to,
        severity: 'error',
        message: invalidLogicalOperator,
      });
    }

    previousNode = { ...node };

    if (node.name === 'FilterGroup') {
      const isClosed = hasClosingBracket(node, tree);

      // Empty group.
      if (
        isClosed &&
        getTextFromRange(
          { from: node.from + 1, to: node.to - 1 },
          view.state.doc,
        ).trim() === ''
      ) {
        builder.add(node.from, node.to, errorMark);
        diagnostics.push({
          from: node.from,
          to: node.to,
          severity: 'error',
          message: '',
          renderMessage: getRenderMessage(emptyGroupError),
        });
      }
    }

    if (node.name === '⚠') {
      builder.add(
        node.from === node.to ? node.from - 1 : node.from,
        node.to,
        node.from === node.to ? postSpotErrorMark : errorMark,
      );

      if (
        node.node.parent?.name === 'FilterGroup' &&
        !hasClosingBracket(node, tree)
      ) {
        diagnostics.push({
          from: node.from - 1,
          to: node.to,
          severity: 'error',
          message: '',
          renderMessage: getRenderMessage(incompleteGroupError),
        });
      } else {
        diagnostics.push({
          from: node.from,
          to: node.to,
          severity: 'error',
          message: '',
          renderMessage: getRenderMessage(incompleteStatementError),
        });
      }
    }

    if (node.name === 'FilterStatement') {
      const { to } = node;
      // Due to errors depending on various parts of the filter statement, we
      // first have to check all the nodes of a statement and set the flags
      // accordingly to be able to determine which errors should be shown.
      let hasKey = false;
      let hasOperator = false;
      let hasInvalidOperator = false;
      let hasValue = false;
      let hasInvalidValue = false;
      let hasIncompleteRange = false;
      let hasIncompleteList = false;

      // There may be multiple errors in one filter statement.
      // We collect the error ranges in this array and then apply them in the correct order.
      const errorRange: FilterFieldNodeRange[] = [];

      const statementCursor = node.node.cursor();
      statementCursor.iterate((node) => {
        // The 'iterate' doc says 'Iterate over the current node and all its descendants', but it
        // continues also with siblings... This is to stop iterating once we leave the filter statement.
        if (node.from >= to) {
          return false;
        }

        if (node.name === 'FilterKey') {
          const keyCursor = node.node.cursor();
          if (keyCursor.firstChild() && keyCursor.node.name === '⚠') {
            errorRange.push({ from: node.from, to: node.to });
          } else {
            hasKey = true;
          }
        }

        // This may happen due to specifically matching a filter statement with only a key and incomplete range
        // for better error handling. The parser's error recovery would not be predictable enough to provide
        // proper error messages.
        if (node.name === 'IncompleteRange') {
          hasValue = true;
          errorRange.push({ from: node.from, to: node.from });
        }

        if (node.name === '⚠') {
          const { from, to } = node;
          errorRange.push({ from, to });

          if (hasKey && hasOperator) {
            hasValue = true;
            hasInvalidValue = true;
          }

          return false;
        }

        if (node.name === 'ComparisonOperator' || node.name === 'Inclusion') {
          hasOperator = true;
        } else if (node.name === 'InvalidComparisonOperator') {
          hasInvalidOperator = true;
          errorRange.push({ from: node.from, to: node.to - 1 });
        } else if (node.name === 'ExistsOperator') {
          hasOperator = true;
          hasValue = true;
        } else if (node.type.is('FilterValue')) {
          hasValue = true;

          statementCursor.iterate((child) => {
            if (node.type.is('FilterValue')) {
              const { from, to } = node;
              const valueCursor = child.node.cursor();

              if (valueCursor.lastChild() && valueCursor.node.name === '⚠') {
                errorRange.push({ from, to });
                hasInvalidValue = true;

                return false;
              }
            }

            if (child.name === 'IncompleteRange') {
              errorRange.push({ from: child.from, to: child.to });
              hasIncompleteRange = true;

              return false;
            }

            if (child.name === 'IncompleteList') {
              errorRange.push({ from: child.from, to: child.to });
              hasIncompleteList = true;

              return false;
            }
          });

          return false;
        }
      });

      if (!hasKey) {
        const range = errorRange.shift();
        if (range) {
          builder.add(range.from, range.to + 1, preSpotErrorMark);
          diagnostics.push({
            from: range.from,
            to: range.to + 1,
            severity: 'error',
            message: '',
            renderMessage: getRenderMessage(missingKeyError),
          });
        }
      }

      if (!hasOperator && !hasValue && !hasInvalidValue) {
        const elm = document.createElement('div');
        elm.innerHTML = 'some text';
        builder.add(to - 1, to, postSpotErrorMark);
        diagnostics.push({
          from: to - 1,
          to,
          severity: 'error',
          message: '',
          renderMessage: getRenderMessage(incompleteStatementError),
        });
      } else {
        if (!hasOperator && errorRange.length > 0) {
          // Either invalid or missing operator error.
          let range = errorRange.shift();
          if (range) {
            if (hasInvalidOperator) {
              builder.add(range.from, range.to, errorMark);
              diagnostics.push({
                from: range.from,
                to: range.to,
                severity: 'error',
                message: '',
                renderMessage: getRenderMessage(invalidOperatorError),
              });
            } else {
              const charBeforeRange = {
                from: range.from - 1,
                to: range.from,
              };
              const charBefore = getTextFromRange(
                charBeforeRange,
                view.state.doc,
              );
              const isSpace = charBefore === ' ';
              hasValue = true;

              range = isSpace
                ? charBeforeRange
                : { from: range.from - 1, to: range.from };
              builder.add(
                range.from,
                range.to,
                isSpace ? errorMark : postSpotErrorMark,
              );
              diagnostics.push({
                from: range.from,
                to: range.to,
                severity: 'error',
                message: '',
                renderMessage: getRenderMessage(missingOperatorError),
              });
            }
          }
        }

        if (!hasValue) {
          builder.add(to - 1, to, postSpotErrorMark);
          diagnostics.push({
            from: to - 1,
            to,
            severity: 'error',
            message: '',
            renderMessage: getRenderMessage(missingValueError),
          });
        }

        const range = errorRange.shift();
        if (range) {
          if (hasInvalidValue) {
            builder.add(range.from, range.to, errorMark);
            diagnostics.push({
              ...range,
              severity: 'error',
              message: '',
              renderMessage: getRenderMessage(invalidValueError),
            });
          }

          if (hasIncompleteRange || hasIncompleteList) {
            builder.add(range.from, range.to, errorMark);
            diagnostics.push({
              ...range,
              severity: 'error',
              message: '',
              renderMessage: hasIncompleteRange
                ? getRenderMessage(incompleteRangeError)
                : getRenderMessage(incompleteListError),
            });
          }
        }
      }

      return false;
    }
  });

  if (messages !== undefined) {
    builder.finish();
    return diagnostics;
  }

  return builder.finish();
}
